#!/usr/bin/env python3
"""Regenerate src/crewline/web/static/js/lib/icons.js from Lucide's icon-nodes.json.

  npm pack lucide-static && tar xzf lucide-static-*.tgz   # gives package/icon-nodes.json
  python3 tools/build_icons.py package/icon-nodes.json mic mic-off headphones ...

Lucide is ISC licensed; keep the attribution in static/vendor/LICENSES.md.
"""
import json
import sys

src, names = sys.argv[1], sys.argv[2:]
nodes = json.load(open(src))
out = {n: nodes[n] for n in names}
open("src/crewline/web/static/js/lib/icons.js", "w").write(
    "// Generated by tools/build_icons.py from Lucide (ISC license). 24x24, stroke icons.\n"
    "// Do not edit by hand.\nexport const ICONS = " + json.dumps(out, separators=(",", ":")) + ";\n")
